window.ScripturaLexicons.BDAG_PART_0236 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-01\" data-source=\"BDAG\" data-search=\"μήτρα, ας, ἡ substantivo feminino útero; ventre materno BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μήτρα, ας, ἡ</td><td>substantivo feminino</td><td>útero; ventre materno</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-02\" data-source=\"BDAG\" data-search=\"μητρολῴας, ου, ὁ substantivo masculino matricida; assassino da própria mãe BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μητρολῴας, ου, ὁ</td><td>substantivo masculino</td><td>matricida; assassino da própria mãe</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-03\" data-source=\"BDAG\" data-search=\"μητρόπολις, εως, ἡ substantivo feminino cidade principal; capital BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μητρόπολις, εως, ἡ</td><td>substantivo feminino</td><td>cidade principal; capital</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-04\" data-source=\"BDAG\" data-search=\"μηχανάομαι verbo médio tramar; urdir; maquinar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μηχανάομαι</td><td>verbo médio</td><td>tramar; urdir; maquinar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-05\" data-source=\"BDAG\" data-search=\"μηχανή, ῆς, ἡ substantivo feminino máquina; guindaste; expediente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μηχανή, ῆς, ἡ</td><td>substantivo feminino</td><td>máquina; guindaste; expediente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-06\" data-source=\"BDAG\" data-search=\"μιαίνω verbo manchar; tornar impuro; contaminar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μιαίνω</td><td>verbo</td><td>manchar; tornar impuro; contaminar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-07\" data-source=\"BDAG\" data-search=\"μιαρός, ά, όν adjetivo imundo; abominável; depravado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μιαρός, ά, όν</td><td>adjetivo</td><td>imundo; abominável; depravado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-08\" data-source=\"BDAG\" data-search=\"μίασμα, ατος, τό substantivo neutro contaminação; crime; ato vergonhoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μίασμα, ατος, τό</td><td>substantivo neutro</td><td>contaminação; crime; ato vergonhoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-09\" data-source=\"BDAG\" data-search=\"μιασμός, οῦ, ὁ substantivo masculino contaminação moral BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μιασμός, οῦ, ὁ</td><td>substantivo masculino</td><td>contaminação moral</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-10\" data-source=\"BDAG\" data-search=\"μίγμα, ατος, τό substantivo neutro mistura; composto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μίγμα, ατος, τό</td><td>substantivo neutro</td><td>mistura; composto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-11\" data-source=\"BDAG\" data-search=\"μίγνυμι verbo misturar; mesclar; combinar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μίγνυμι</td><td>verbo</td><td>misturar; mesclar; combinar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-12\" data-source=\"BDAG\" data-search=\"μικρολογία, ας, ἡ substantivo feminino ninharia; trivialidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μικρολογία, ας, ἡ</td><td>substantivo feminino</td><td>ninharia; trivialidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-13\" data-source=\"BDAG\" data-search=\"μικρός, ά, όν adjetivo pequeno; curto; insignificante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μικρός, ά, όν</td><td>adjetivo</td><td>pequeno; curto; insignificante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-14\" data-source=\"BDAG\" data-search=\"μικρῶς advérbio ligeiramente; um pouco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μικρῶς</td><td>advérbio</td><td>ligeiramente; um pouco</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-15\" data-source=\"BDAG\" data-search=\"Μίλητος, ου, ἡ nome próprio feminino Mileto; cidade da Ásia Menor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μίλητος, ου, ἡ</td><td>nome próprio feminino</td><td>Mileto; cidade da Ásia Menor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-16\" data-source=\"BDAG\" data-search=\"μίλιον, ου, τό substantivo neutro milha romana BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μίλιον, ου, τό</td><td>substantivo neutro</td><td>milha romana</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-17\" data-source=\"BDAG\" data-search=\"μιμέομαι verbo depoente imitar; emular; seguir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μιμέομαι</td><td>verbo depoente</td><td>imitar; emular; seguir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-18\" data-source=\"BDAG\" data-search=\"μίμημα, ατος, τό substantivo neutro cópia; imagem; imitação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μίμημα, ατος, τό</td><td>substantivo neutro</td><td>cópia; imagem; imitação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-19\" data-source=\"BDAG\" data-search=\"μιμητής, οῦ, ὁ substantivo masculino imitador; seguidor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μιμητής, οῦ, ὁ</td><td>substantivo masculino</td><td>imitador; seguidor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0236-20\" data-source=\"BDAG\" data-search=\"μιμνῄσκομαι verbo médio lembrar; recordar; mencionar; considerar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μιμνῄσκομαι</td><td>verbo médio</td><td>lembrar; recordar; mencionar; considerar</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0236-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μήτρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μήτρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">μήτηρ</span>; Hdt., Pla. e outros; papiros [BGU 1026, 22, 20; APF 5, 1913, 393 n.º 312, 10ff]; LXX; TestAbr A 8 p. 85, 18 [Stone p. 18]; Apc4Esdr Fgm. a; Philo; SibOr, Fgm. 3, 2; Just.; Mel., P. 66, 468; Ath. 22, 4; empréstimo no rabínico), útero, ventre materno: <span class=\"greek\">ἡ</span> <span class=\"greek\">νέκρωσις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">Σάρρας</span>, a esterilidade do ventre de Sara <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:19</a>; GJs 2:4, variante de leitura; <span class=\"greek\">τὴν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">σου</span> 2:3; <span class=\"greek\">ποία</span> … <span class=\"greek\">μ</span>. 3:1. Dos primogênitos: <span class=\"greek\">πᾶν</span> <span class=\"greek\">ἄρσεν</span> <span class=\"greek\">διανοῖγον</span> <span class=\"greek\">μήτραν</span>, todo macho que abre a madre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:23</a> (ver <span class=\"greek\">διανοίγω</span> 1a).—DELG s.v. <span class=\"greek\">μήτηρ</span> C. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητρολῴας, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μητρολῴας</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">μήτηρ</span>, <span class=\"greek\">ἀλοιάω</span>, “golpear”); no NT, os manuscritos também atestam a forma posterior <span class=\"greek\">μητραλῴας</span> (B-D-F §26; 35, 2; 119, 2; Mlt-H. 68.—Ático <span class=\"greek\">μητραλοίας</span> Aeschyl. e outros; Pla., Phd. 113e; 114a <span class=\"greek\">πατραλοῖαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μητραλοῖαι</span>, Leg. 9, 881a <span class=\"greek\">μητραλοῖαι</span> … <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">τολμήσῃ</span> <span class=\"greek\">μητέρα</span> <span class=\"greek\">τύπτειν</span>.—Lysias 10, 8; Lucian, Deor. Conc. 12; AscIs 4:2), aquele que mata a própria mãe, matricida (com <span class=\"greek\">πατρολῴας</span>. Sobre esses termos muito fortes num catálogo de vícios, cf. Physiogn. I 327, 15 <span class=\"greek\">πατροφόνοι</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μητροφόνοι</span> <span class=\"greek\">παιδοφθόροι</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φαρμακοὶ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅμοια</span> <span class=\"greek\">τούτων</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:9</a>.—DELG s.v. <span class=\"greek\">ἀλωή</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μητρόπολις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μητρόπολις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">μήτηρ</span>, <span class=\"greek\">πόλις</span>; Pind., Hdt. e outros), cidade principal, capital (assim X., An. 5, 2, 3; 5, 4, 15; Diod S 17, 70, 1; Strabo 16, 2, 44; Dio Chrys. 16 [33], 17; inscrições, papiros, LXX, JosAs cap. 16 cód. A [p. 64, 19 Bat.], em imagem de Asenete como promessa; Philo; Jos., Ant. 4, 82; 12, 119) 1 Ti, subscrição (ver <span class=\"greek\">Πακατιανός</span>).—New Docs 1, n.º 12, 13 (198/199 d.C.). M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανάομαι</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μηχανάομαι</span> (<span class=\"greek\">μηχανή</span>), imperfeito na 3ª pessoa singular <span class=\"greek\">ἐμηχανᾶτο</span>; particípio perfeito <span class=\"greek\">μεμηχανημένος</span> 3 Macc 5:28 (passivo) (“construir, elaborar engenhosamente” alguma coisa, Hom. e outros, tanto em bom quanto em mau sentido; em nossa literatura, apenas neste último): realizar maquinações engenhosas, tramar, urdir <span class=\"greek\">τὶ</span>, alguma coisa (Hom. e outros; CPR I, 19, 19 <span class=\"greek\">ταῦτα</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐμηχανήσατο</span> = ele próprio concebeu tudo isso; 3 Macc 6:24; Philo, Virt. 42; Jos., Ant. 17, 17, Vi. 53; SibOr 126; 172) <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>, tramar estratagemas contra alguém (TestReub 5:3; cf. Vi. Aesopi G 3 P. <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἄλλου</span> <span class=\"greek\">μηχανεύεσθαι</span> <span class=\"greek\">κακόν</span>) MPol 3.—DELG s.v. <span class=\"greek\">μηχανή</span> 5.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μηχανή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μηχανή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (desde Hes.), em geral, “máquina” (Aeschyl., Hdt.+; inscrições, papiros, LXX; TestSol 26:8 PQ [fig. “artifício, estratagema”]; Philo; Jos., Ant. 14, 423; 17, 4; Tat. 3, 1; 17, 2 [fig.]; empréstimo no rabínico); especificamente, guindaste para erguer objetos (Pla., Crat. 425d); figuradamente, <span class=\"greek\">μ</span>. <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span> IEph 9:1. A imagem desenvolve-se assim: as partes do “guindaste de Cristo” são a cruz (Hdt. 2, 125 <span class=\"greek\">μηχ</span>. <span class=\"greek\">ξύλων</span> = “feito de madeira”) e o Espírito Santo, sendo este último a corda. O guindaste eleva as pedras, que simbolizam os cristãos, à altura adequada para a construção divina (cf. Chrysostom, Hom. 3 in Eph <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">διά</span> <span class=\"greek\">τινος</span> <span class=\"greek\">ἕλκων</span> <span class=\"greek\">μηχανῆς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὕψος</span> <span class=\"greek\">αὐτὴν</span> [sc. <span class=\"greek\">ἐκκλησίαν</span>] <span class=\"greek\">ἀνήγαγε</span> <span class=\"greek\">μέγα</span>; Martyr. Andreae 1, 14 [Aa II/1, 55] <span class=\"greek\">ὦ</span> <span class=\"greek\">σταυρὲ</span> <span class=\"greek\">μηχάνημα</span> <span class=\"greek\">σωτηρίας</span>).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιαίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μιαίνω</span> (Hom.+); futuro <span class=\"greek\">μιανῶ</span> (Hs 5, 7, 2); 1º aoristo <span class=\"greek\">ἐμίανα</span>, particípio <span class=\"greek\">μιάνας</span>. Passivo: futuro na 3ª pessoa singular <span class=\"greek\">μιανθήσεται</span> LXX; 1º aoristo <span class=\"greek\">ἐμιάνθην</span>; perfeito <span class=\"greek\">μεμίαμμαι</span>, particípio <span class=\"greek\">μεμιαμμένος</span> (B-D-F §72; W-S. §13, 1; Mlt-H. 223; 249). O sentido primário, “manchar” (como com tinta ou corante [Il. 4, 141]), prepara o sentido transferido de provocar contaminação por comportamento social ou culticamente inaceitável. Convém recordar, quanto ao uso deste termo e seus cognatos, que no mundo greco-romano se entendia que relações harmoniosas com a esfera transcendente dependiam da observância cuidadosa de determinadas normas morais e rituais. Os indivíduos estavam subordinados aos interesses da comunidade, e a violação das expectativas morais e cerimoniais estabelecidas poderia pôr em perigo o delicado equilíbrio entre toda uma população e suas divindades. Em nossa literatura, apenas no sentido transferido.</p><p class=\"entry-text\">① Tornar alguma coisa ritualmente impura, manchar, contaminar (Jos., Bell. 4, 201; 215, Ant. 11, 300 e outros; GJs 8:2); passivo <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">μιανθῶσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:28</a> (cf. 1 Macc 1:63 <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">μιανθῶσιν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">βρώμασι</span>). Sobre o assunto, ver Schürer II 83f; Bousset, Rel.3 93f.</p><p class=\"entry-text\">② Fazer com que a pureza de alguma coisa seja violada por comportamento imoral, macular, contaminar (Pind., Aeschyl. e outros; Kaibel 713, 9 <span class=\"greek\">οὐ</span> <span class=\"greek\">χεῖρα</span> <span class=\"greek\">φόνοισι</span> <span class=\"greek\">μιάνας</span>. Menos frequentemente em prosa, por exemplo SIG 1240, 7 <span class=\"greek\">ὑβρίσει</span> <span class=\"greek\">μιάνας</span>; PFlor 338, 18; LXX; EpArist 166; Philo; Jos., Bell. 4, 323) <span class=\"greek\">τὶ</span>, alguma coisa: <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:38</a> D. <span class=\"greek\">σάρκα</span> Jd 8; Hm 4, 1, 9; Hs 5, 7, 2–4. <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> 5, 6, 5; 5, 7, 2. <span class=\"greek\">ἑαυτόν</span> 9, 17, 5. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐντολὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, profanar o mandamento do Senhor m 3:2; cf. Hs 9, 29, 2. De Eva: <span class=\"greek\">ὁ</span> <span class=\"greek\">ὄφις</span> … <span class=\"greek\">ἐμίανεν</span> <span class=\"greek\">αὐτὴν</span> GJs 13:1. De Maria: <span class=\"greek\">Ἰωσὴφ</span> … <span class=\"greek\">ἐμίανεν</span> <span class=\"greek\">αὐτήν</span> 15:2 (JosAs 23:13).—Passivo (UPZ 78, 27 [159 a.C.]; En 12:4; frequentemente em Philo; TestBenj 8:3; Ar. 12:1): <span class=\"greek\">ἡ</span> <span class=\"greek\">πορεία</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ταύτης</span> … <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐμιάνθη</span> Hs 5, 6, 6. O Espírito Santo, que habita numa pessoa, é contaminado quando ela se encoleriza m 5, 1, 3; igualmente a paciência 5, 1, 6. A mente dos descrentes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:15b</a>. O afastamento da graça de Deus conduz à contaminação pelo pecado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:15</a>. Substantivado: <span class=\"greek\">ὁ</span> <span class=\"greek\">μεμιαμμένος</span>, aquele que está contaminado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:15a</a> (JPlumpe, Theol. Studies 6, ’45, 509–23).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιαρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μιαρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">μιαίνω</span>; Hom. e outros; SIG 218, 86; PCairMasp 97 II, 45; 2 e 4 Macc; Jos., Ant. 18, 38, C. Ap. 1, 236), sentido primário “maculado, poluído” (ver <span class=\"greek\">μιαίνω</span>); depois transferido, e somente assim em nossa literatura: relativo ao que viola normas cultuais ou morais a ponto de causar repulsa, abominável, miserável, imundo, depravado, lascivo (Soph. e outros; Hyperid. 5, 32; 2 e 4 Macc; Philo; SibOr 3, 667; Tat., Ath.) <span class=\"greek\">ἐπιθυμίαι</span> 1 Cl 28:1; (com <span class=\"greek\">ἀνόσιος</span>, como em Heraclit. Sto. 76 p. 100, 12; PGM 4, 2475) <span class=\"greek\">στάσις</span> 1:1; (com <span class=\"greek\">ἄναγνος</span>) <span class=\"greek\">συμπλοκαί</span> 30:1; (com <span class=\"greek\">ἄδικος</span>) <span class=\"greek\">ζῆλος</span> 45:4.—DELG s.v. <span class=\"greek\">μιαίνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίασμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μίασμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">μιαίνω</span>; Aeschyl. e outros; LXX), na literatura grega, contaminação vinculada a um crime (Antiphon 5, 82, com “mãos impuras”, de alguma contaminação que expõe os companheiros a perigos especiais no mar; Ps.-Demosth. 59, 86 [com <span class=\"greek\">ἀσεβήματα</span>], causada por adultério; Polyb. 36, 16, 6; Jdth 13:16; En 10:22; Philo; Jos., Bell. 2, 455; Ath. 35, 2), também com ênfase no próprio crime: ato vergonhoso, delito, crime (assim claramente Conon [I a.C./I d.C.]: 26 Fgm. 1, 48, 3 Jac.: <span class=\"greek\">τὸ</span> <span class=\"greek\">μίασμα</span> <span class=\"greek\">πρᾶξαι</span>; Polyaenus 6, 7, 2 <span class=\"greek\">κοινωνία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μιάσματος</span> = participação no crime; Ezk 33:31) <span class=\"greek\">ἀποφυγεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:20</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">μοιχείας</span> ApcPt 9:24.—DELG s.v. <span class=\"greek\">μιαίνω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιασμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μιασμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">μιαίνω</span>) (“poluição, corrupção”, Plut., Mor. 393c, Sol. 12, 3; Iambl., Protr. 21, 16 p. 116, 5 Pistelli; LXX; Test12Patr), uso figurado apenas em referência à esfera moral (Proclus sobre Pla., Rep. II 354, 20 Kr. <span class=\"greek\">μ</span>. <span class=\"greek\">ψυχῶν</span>; Wsd 14:26 <span class=\"greek\">ψυχῶν</span> <span class=\"greek\">μ</span>.; TestLevi 17:8, Benj 8:2f), contaminação; de excessos: <span class=\"greek\">παραχρῆσθαι</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τινι</span>, usar indevidamente a carne em alguma contaminação Hs 5, 7, 2. <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐπιθυμίᾳ</span> <span class=\"greek\">μιασμοῦ</span> <span class=\"greek\">πορεύεσθαι</span>, seguir a carne em desejo corruptor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:10</a>.—RParker, Miasma, Pollution and Purification in Early Gk. Religion ’83. DELG s.v. <span class=\"greek\">μιαίνω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίγμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μίγμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">μίγ</span>. [talvez <span class=\"greek\">μεῖγ</span>.] B-D-F §13; Mlt-H. 57.—Aristot. e outros; Plut., Mor. 997a; Athen. 15, 17, 675bc; PGM 7, 867; Sir 38:7; Philo, Ebr. 191), mistura, combinação; de um unguento: <span class=\"greek\">μ</span>. <span class=\"greek\">σμύρνης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀλόης</span>, mistura de mirra e aloés <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:39</a> (variantes de leitura <span class=\"greek\">ἕλιγμα</span>, <span class=\"greek\">σμῆγμα</span>, <span class=\"greek\">σμίγμα</span>; ver esses verbetes).—DELG s.v. <span class=\"greek\">μείγνυμι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίγνυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μίγνυμι</span>/<span class=\"greek\">μιγνύω</span> (o presente não ocorre em nossa literatura [B-D-F §92; Mlt-H. 249], nem nos papiros ptolemaicos [Mayser I/22, ’38, 187].—Sobre a grafia [<span class=\"greek\">μιγ</span>- em todas as edições, em lugar de <span class=\"greek\">μειγ</span>-], ver B-D-F §23; Kühner-Bl. II 482; Mayser 91; Mlt-H. 249.—A palavra ocorre em Hom. [<span class=\"greek\">μίσγω</span>] e outros; também inscrições, papiros, LXX, TestSol, Joseph., Just., Ath.); 1º aoristo <span class=\"greek\">ἔμιξα</span>. Passivo: particípio do 1º aoristo <span class=\"greek\">μιχθείς</span> (Ath. 18, 4); 2º aoristo <span class=\"greek\">ἐμίγην</span>; particípio perfeito <span class=\"greek\">μεμιγμένος</span>; misturar, mesclar, literalmente: <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, misturar alguma coisa com outra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:2</a> (Chariton 3, 10, 2 <span class=\"greek\">αἵματι</span> <span class=\"greek\">μεμιγμένον</span> <span class=\"greek\">ὕδωρ</span>; Quint. Smyrn. 6, 281 <span class=\"greek\">οἴνῳ</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">αἷμα</span> <span class=\"greek\">μέμικτο</span>; escólio sobre Nicander, Alexiph. 353). Também <span class=\"greek\">τὶ</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> (cf. Ps 105:35) 8:7. <span class=\"greek\">τὶ</span> <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> (Pla., Tim. 35b) <span class=\"greek\">οἶνον</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">χολῆς</span> <span class=\"greek\">μεμιγμένον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:34</a>. <span class=\"greek\">ὧν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αἷμα</span> <span class=\"greek\">Πιλᾶτος</span> <span class=\"greek\">ἔμιξεν</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θυσιῶν</span> <span class=\"greek\">αὐτῶν</span>, cujo sangue Pilatos misturou com (o sangue de) seus sacrifícios, isto é, pessoas que P. mandou matar enquanto sacrificavam <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:1</a> (sobre a questão da relação com relatos de Jos., ver JFitzmyer, AB Comm. ad loc.). <span class=\"greek\">ὄξος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἶνος</span> <span class=\"greek\">μεμιγμένα</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτό</span>, vinagre e vinho misturados Hm 10, 3, 3b.—Em linguagem figurada afetiva, misturar, combinar: <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, alguma coisa com outra (Jos., Bell. 5, 332, Ant. 15, 52) <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀξυχολία</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">μακροθυμίᾳ</span> 5, 1, 6. <span class=\"greek\">τὶ</span> <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span>: <span class=\"greek\">ἡ</span> <span class=\"greek\">λύπη</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐντεύξεως</span>, … <span class=\"greek\">μετὰ</span> <span class=\"greek\">του</span> <span class=\"greek\">ἁγίου</span> <span class=\"greek\">πνεύματος</span> 10, 3, 3ac.—B. 335. DELG s.v. <span class=\"greek\">μείγνυμι</span>. M-M. s.v. <span class=\"greek\">μίγν</span>-.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικρολογία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μικρολογία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (“assunto pequeno”, Pla. e outros), algo de pouca ou nenhuma importância, ninharia, trivialidade em sentido depreciativo (Pla., Hipp. Maj. 304b, acerca de preciosismo numa discussão; Lucian, Vit. Auct. 17; Philo, Somn. 1, 94) Hm 5, 2, 2.—DELG s.v. <span class=\"greek\">μικρός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μικρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (“pequeno”; Hom.+), comparativo <span class=\"greek\">μικρότερος</span>, <span class=\"greek\">έρα</span>, <span class=\"greek\">ον</span>.</p><p class=\"entry-text\">① Relativo a tamanho, medida ou quantidade comparativamente limitados, pequeno, curto.</p><p class=\"entry-text\">ⓐ Da estatura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:3</a>. Talvez também <span class=\"greek\">Ἰάκωβος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μικρός</span> (<span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. após o nome de uma pessoa: Aristoph., Ran. 708; X., Mem. 1, 4, 2; Aristot., Pol. 5, 10 p. 1311b, 3; Diog. L. 1, 79 sobre um Pítaco “mais jovem”; Sb 7576, 6 [I d.C.]; 7572, 10 [II d.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:40</a> (ver <span class=\"greek\">Ἰάκωβος</span> 3). Essa passagem possivelmente pertence a</p><p class=\"entry-text\">ⓑ Da idade. Substantivado: o pequeno, a criança (<span class=\"greek\">ὁ</span> <span class=\"greek\">μικρός</span> Menand., Sam. 39f; PLond 893, 7 [40 d.C.]; PFay 113, 14. <span class=\"greek\">ἡ</span> <span class=\"greek\">μικρά</span> PLond III, 899, 6 p. 208 [II d.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:6</a>, 10, 14.—Quanto à designação de todos os membros de um grupo como <span class=\"greek\">μικροὶ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μεγάλοι</span> etc., cf. <span class=\"greek\">μέγας</span> 1d: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:10</a>; 26:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:11</a> (Jer 38:34); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:18</a>; 13:16; 19:5, 18; 20:12.</p><p class=\"entry-text\">ⓒ Da distância. Advérbio: a curta distância, um pouco adiante (X., Cyr. 1, 2, 15; Dionys. Byz. §8 e 13) <span class=\"greek\">προελθὼν</span> <span class=\"greek\">μικρόν</span> (Ps.-Demetr. 226) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:35</a>.</p><p class=\"entry-text\">ⓓ Do tempo.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Adjetivo: curto, do tempo <span class=\"greek\">χρόνον</span> <span class=\"greek\">μικρόν</span> (Pla., Rep. 6, 498d; Ael. Aristid. 34 p. 661 D.; Is 54:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:33</a>; cf. 12:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:11</a>; 20:3.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Advérbio: pouco tempo, breve intervalo (Jos., Ant. 4, 159; 8, 405) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:33</a> (cf. Job 36:2); Hs 9, 4, 4; 9, 5, 1 (variante de leitura). <span class=\"greek\">μικρόν</span>, por um momento (Menand., Epitr. 474 J.=538 Kö.; JosAs 15:14; ParJer 2:9; cf. <span class=\"greek\">πρὸς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">μ</span>., “pouco a pouco”, GrBar 7:3) Hv 4, 1, 6. <span class=\"greek\">μετὰ</span> <span class=\"greek\">μικρόν</span>, depois de pouco tempo (Just., D. 56, 17; Phlegon: 257 Fgm. 36, 1, 2 Jac.; Lucian, Dial. Mort. 15, 3; Synes., Dio 1 p. 234, 5 NTerzaghi [’44]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.73\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:73</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.70\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:70</a>. (<span class=\"greek\">ἔτι</span>) <span class=\"greek\">μικρὸν</span> <span class=\"greek\">καί</span> …, dentro em pouco, literalmente “ainda um pouco, e” = logo (Ex 17:4; Jer 28:33; Hos 1:4; TestJob 24:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:19</a>; 16:16–19. <span class=\"greek\">ἔτι</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ὅσον</span> <span class=\"greek\">ὅσον</span> = em breve <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.37\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:37</a>; 1 Cl 50:4 (ambos Is 26:20; ver B-D-F §127, 2; 304; Rob. 733).</p><p class=\"entry-text\">ⓔ Da massa ou extensão relativa a coisas.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Pequeno (X., Mem. 3, 14, 1 <span class=\"greek\">μ</span>. <span class=\"greek\">ὄψον</span>; TestAbr B 8 p. 112, 20 [Stone p. 72] <span class=\"greek\">πύλη</span>; ApcSed 11:3 <span class=\"greek\">μ</span>. <span class=\"greek\">κτίσμα</span>; ViIs, ViEzk, ViHab, ViJer e outros 3 [p. 69, 7 Sch.] <span class=\"greek\">ὕδωρ</span>; Just., A I, 19, 1 <span class=\"greek\">ῥανίς</span>) <span class=\"greek\">μικρότερον</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σπερμάτων</span>, a menor de todas as sementes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:31</a> (ver <span class=\"greek\">σίναπι</span>.—Alex. Aphr., An. II 1 p. 20, 14 <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">κωλυθήσεται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέγιστον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μικροτάτῳ</span> <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">σώματι</span>). <span class=\"greek\">μικρὰ</span> <span class=\"greek\">ζύμη</span>, um pouco de fermento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:9</a>. Da língua: <span class=\"greek\">μικρὸν</span> <span class=\"greek\">μέλος</span>, pequeno membro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:5</a> (cf. Eur., Fgm. TGF 411).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Neutro substantivado: (<span class=\"greek\">τὸ</span>) <span class=\"greek\">μικρόν</span>, aquilo que é insignificante, pequeno: <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τηρεῖν</span> 2 Cl 8:5 (dito apócrifo de Jesus). <span class=\"greek\">μικρὰ</span> <span class=\"greek\">φρονεῖν</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, ter pouca consideração por algo 2 Cl 1:1f (<span class=\"greek\">μικρὸν</span> <span class=\"greek\">φρονεῖν</span> Soph., Aj. 1120; Plut., Mor. p. 28c).—Plural: coisas insignificantes, ninharias (Aelian, VH 2, 27) <span class=\"greek\">μικρὰ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἀλλήλων</span> <span class=\"greek\">ἔχειν</span>, ter queixas triviais uns contra os outros Hs 8, 10, 1b.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Neutro substantivado: um pouco: <span class=\"greek\">μικρόν</span> <span class=\"greek\">τι</span> (Diod S 1, 74, 1; Ael. Aristid. 48, 37 K.=24 p. 474 D.; UPZ 70, 3 [152/151 a.C.]; cf. Just., D. 115, 6 <span class=\"greek\">ἓν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ὁτιοῦν</span>) um pouco <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:16</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἀφροσύνης</span>, versículo 1 (Procop. Soph., Ep. 80 <span class=\"greek\">μοὶ</span> <span class=\"greek\">μικρὸν</span> <span class=\"greek\">δίδου</span> <span class=\"greek\">νεανιεύεσθαι</span>). <span class=\"greek\">παρὰ</span> <span class=\"greek\">μικρόν</span> (Isocr. 19, 22; Dionys. Byz. §3 e 50; Ps 72:2; Ezk 16:47; PsSol 16:1; Jos., C. Ap. 2, 270), por pouco, quase Hs 8, 1, 14. <span class=\"greek\">κατὰ</span> <span class=\"greek\">μικρόν</span>, em resumo (Galen XIX p. 176 K.: Lucian, Catapl. 17, De Merc. Cond. 35) 1:5. <span class=\"greek\">μικροῦ</span> <span class=\"greek\">δεῖν</span>, por pouco, quase AcPl Ha 3, 34 (Jos., C. Ap. 2, 168 e outros).</p><p class=\"entry-text\">ⓕ Pequeno em número (Gen 30:30; 47:9) <span class=\"greek\">τὸ</span> <span class=\"greek\">μικρὸν</span> <span class=\"greek\">ποίμνιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:32</a>.</p><p class=\"entry-text\">② Relativo à pouca importância, sem importância, insignificante.</p><p class=\"entry-text\">ⓐ De pessoas destituídas de importância, influência, poder etc. <span class=\"greek\">εἷς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μικρῶν</span> <span class=\"greek\">τούτων</span>, um destes humildes (discípulos? assim Goodsp.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:42</a> (Kephal. I 189, 6–19; 201, 30 interpreta “os pequeninos que creem” como catecúmenos. Mas a palavra grega <span class=\"greek\">μικρός</span> não aparece no texto copta); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:2</a>. OMichel, ‘Diese Kleinen’, e. Jüngerbezeichnung Jesu: StKr 108, ’37/38, 401–15. <span class=\"greek\">ὁ</span> <span class=\"greek\">μικρότερος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">βασιλείᾳ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανῶν</span>, aquele de menor importância no Reino dos Céus (mas FDibelius, ZNW 11, 1910, 190–92, e OCullmann, ConNeot 11, ’47, 30, preferem “mais jovem” e o relacionam a Cristo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:11</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:28</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">μικρότερος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ὑπάρχων</span>, aquele que é o menor entre todos vós 9:48.</p><p class=\"entry-text\">ⓑ Pequeno, insignificante (Ath. 23, 3 <span class=\"greek\">δόξαι</span>) <span class=\"greek\">δύναμις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:8</a>. <span class=\"greek\">μισθός</span> 2 Cl 15:1b (cf. a: <span class=\"greek\">μ</span>. <span class=\"greek\">συμβουλία</span>). <span class=\"greek\">ἐπιθυμίαι</span> Hs 8, 10, 1a.</p><p class=\"entry-text\">③ O estado de ser pequeno, pequenez, neutro substantivado: <span class=\"greek\">ἐκ</span> <span class=\"greek\">μικροῦ</span> <span class=\"greek\">αὐξῆσαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:28</a> D.—B. 880. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μικρῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μικρῶς</span> (Pla.; 2 Macc 14:8; Jos., Ant. 15, 213, variante de leitura), advérbio de <span class=\"greek\">μικρός</span>: ligeiramente, um pouco: <span class=\"greek\">οὐ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ὠργίζετο</span> AcPl Ha 3, 2; semelhantemente <span class=\"greek\">λυπέω</span> 4, 17; <span class=\"greek\">πενθέω</span> 5, 19; <span class=\"greek\">ἀγωνιάω</span> 7, 31.—DELG. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μίλητος, ου, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μίλητος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; inscrições; SibOr 5, 325), Mileto, cidade portuária na costa ocidental da Ásia Menor, ao sul das desembocaduras do Meandro, cerca de 60 km ao sul de Éfeso. Havia uma comunidade judaica em M. (Schürer III 24f; 117, 2; 167f; AvGerkan, E. Synagoge in Milet: ZNW 20, 1921, 177–81; Dssm., LO 391f [LAE 451f]). Paulo aportou à cidade em sua última viagem a Jerusalém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:15</a>, 17 (sobre o discurso de despedida de Paulo, ver JLambrecht em Les Actes des Apôtres ’79, 307–37; WKurz, Farewell Addresses in the NT ’90). Segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:20</a>, Trófimo estava enfermo em Mileto.—TWiegand, ed., Milet. Ergebnisse der Ausgrabungen u. Untersuchungen seit d. Jahre 1899 (1906ff), 18 vols.; PECS s.v. (bibliografia); Pauly-W. XV 1586–1655; Kl. Pauly III 1295–98; BHHW II 1216f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίλιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μίλιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Eratosthenes [em Julian of Ashkelon, Metr. Script. I 201]; Polyb. 34, 12, 3; Strabo 3, 1, 9; 5, 1, 11 e outros; Plut., Cic. 32, 1, C. Gracch. 7, 3; IGR III, 1385; SIG 888, 26; BCH 29, 1905, 99f; APF 2, 1903, 566 n.º 122; PStras 57, 6. Empréstimo latino: mille. Também empréstimo no rabínico), milha romana, literalmente mil passos, depois uma medida fixa = oito estádios = 1,478.5 metros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:41</a>; D 1:4; GJs 17:2.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιμέομαι</h1><div class=\"entry-meta\"><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μιμέομαι</span> (<span class=\"greek\">μῖμος</span>, “imitador, mímico”), médio depoente; imperativo <span class=\"greek\">μιμοῦ</span>; imperfeito <span class=\"greek\">ἐμιμούμην</span>; futuro <span class=\"greek\">μιμήσομαι</span>; 1º aoristo <span class=\"greek\">ἐμιμησάμην</span> (Pind.+), tomar como modelo, imitar, emular, seguir, com acusativo de pessoa e, em nossa literatura, apenas do comportamento (Ael. Aristid. 34 p. 669 D.; Wsd 15:9; Philo; Jos., Ant. 6, 347, C. Ap. 2, 257; Tat. 7, 3) ISm 12:1. <span class=\"greek\">ἡμᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:7</a>, 9 (PFlor 367, 3 <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μειμήσομαί</span> <span class=\"greek\">σε</span>). <span class=\"greek\">θεόν</span> Dg 10:5 (Heraclitus, Ep. 5, 1 <span class=\"greek\">θεόν</span>; Eunap. 104 sobre o médico Oribásio: <span class=\"greek\">ἐμιμεῖτο</span> <span class=\"greek\">θεόν</span> [Asclépio]; EpArist 281; Philo, Spec. Leg. 4, 73, Virt. 168; TestAsh 4:3 <span class=\"greek\">κύριον</span>; Did., Gen. 57, 22; 180, 9).—De Cristo: <span class=\"greek\">ἂν</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">μιμήσεται</span>, <span class=\"greek\">καθὰ</span> <span class=\"greek\">πράσσομεν</span>, se ele imitasse nosso modo de proceder IMg 10:1. Com acusativo de coisa: imitar algo (Appian, Samn. 10 §1 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀρετήν</span>; TestAbr 20 p. 104, 6 [Stone p. 56] <span class=\"greek\">τὴν</span> <span class=\"greek\">φιλοξενίαν</span>; Philo, Congr. Erud. Gr. 69 <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐκείνων</span> <span class=\"greek\">βίον</span> e outros; Jos., Ant. 12, 241, C. Ap. 1, 165; Iren. 1, 17, 2 [Harv. I 168, 7;11]) <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:7</a>. Copiar <span class=\"greek\">τὶ</span>, alguma coisa: <span class=\"greek\">τὸ</span> <span class=\"greek\">κακόν</span>, <span class=\"greek\">ἀγαθόν</span> (Sotades 7, 2 <span class=\"greek\">μιμοῦ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">καλόν</span> [Coll. Alex. p. 241]; Kaibel 85, 3 <span class=\"greek\">ἐμιμούμην</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">καλόν</span>; EpArist 188; Just., A I, 10, 1 <span class=\"greek\">ἀγαθά</span>) 3J 11. <span class=\"greek\">τὸ</span> <span class=\"greek\">μαρτύριον</span> MPol 19:1.—DELG s.v. <span class=\"greek\">μῖμος</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίμημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μίμημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">μιμέομαι</span>; Aeschyl. e outros; Musonius 90, 40 um ser humano é <span class=\"greek\">μ</span>. <span class=\"greek\">θεοῦ</span>; Polemo, Decl. 2, 32 p. 27, 7; OGI 383, 63; 404, 26; Wsd 9:8. Frequentemente Philo; Jos., Bell. 7, 142, Ant. 12, 75; Just., A II, 13, 6; SibOr 8, 116), aquilo que é imitado, cópia, imagem: <span class=\"greek\">δέχεσθαι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθοῦς</span> <span class=\"greek\">ἀγάπης</span>, receber as cópias do Verdadeiro Amor (isto é, de Cristo), talvez com referência a Inácio e aos companheiros de prisão (ver JKleist, tradução, ad loc.) Pol 1:1 (Herm. Wr. 382, 18 Sc. <span class=\"greek\">μ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἀληθείας</span>).—DELG s.v. <span class=\"greek\">μῖμος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιμητής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μιμητής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">μιμέομαι</span>; X., Pla. e outros; Philo, Joseph.), imitador, em nossa literatura usado sobretudo com <span class=\"greek\">εἶναι</span> ou <span class=\"greek\">γίνεσθαι</span>.</p><p class=\"entry-text\">ⓐ Com genitivo da pessoa imitada (X., Mem. 1, 6, 3 <span class=\"greek\">οἱ</span> <span class=\"greek\">διδάσκαλοι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">μαθητὰς</span> <span class=\"greek\">μιμητὰς</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">ἀποδεικνύουσιν</span>; Jos., Ant. 1, 109; 12, 203 <span class=\"greek\">μιμ</span>. <span class=\"greek\">γίν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">γεγεννηκότος</span>) <span class=\"greek\">μιμηταί</span> <span class=\"greek\">μου</span> <span class=\"greek\">γίνεσθε</span>, tomai-me como vosso modelo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:16</a> (BSanders, HTR 74, ’81, 353–63); 11:1 (EEidem, Imitatio Pauli: Festskrift for EStave 1922, 67–85; WPdeBoer, The Imitation of Paul ’62; ELarsson, Christus als Vorbild [tese de Uppsala] ’62; ASchulz, Nachfolgen u. Nachahmen ’62; bibliografia adicional em EGüttgemanns, D. leidende Apostel, ’66, 185–94; CSpicq, BRigaux Festschr., ’70, 313–22). Cf. 1 Cl 17:1. <span class=\"greek\">μιμηταὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κληρονομούντων</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐπαγγελίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:12</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:6</a> (TRE XXIII 685f). <span class=\"greek\">τ</span>. <span class=\"greek\">κυρίου</span> IEph 10:3; MPol 17:3; cf. 1:2. <span class=\"greek\">Χριστοῦ</span> IPhld 7:2; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:1</a>. (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">θεοῦ</span> (Did., Gen. 180, 11; Just., A I, 21, 4 <span class=\"greek\">θεῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:1</a>; Dg 10:4b, 6; IEph 1:1; ITr 1:2.—EGulin, Die Nachfolge Gottes: Studia Orientalia I, ed. Societas Orientalis Fennica 1925, 34–50; FTillmann, D. Idee der Nachfolge Christi ’34; JNielen em Hlg. Überliefg. (ed. OCasel) ’38, 59–85.</p><p class=\"entry-text\">ⓑ Com genitivo impessoal (Herodian 6, 8, 2 <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνδρείας</span>; Philo, Virt. 66; Jos., Ant. 1, 68; 8, 251; <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀρετῆς</span> Did., Gen. 144, 24) <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐκκλησιῶν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:14</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀγαθοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:13</a>, variante de leitura. <span class=\"greek\">τῆς</span> <span class=\"greek\">χρηστότητος</span> Dg 10:4a. <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑπομονῆς</span> Pol 8:2. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πάθους</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> IRo 6:3.—DELG s.v. <span class=\"greek\">μῖμος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0236-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μιμνῄσκομαι</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μιμνῄσκομαι</span>; a maioria dos manuscritos não apresenta iota subscrito, que é secundário; sobre a grafia, ver B-D-F §26; forma alternativa do presente <span class=\"greek\">μνῄσκομαι</span> (1 Macc 6:12, variante de leitura; TestJob 35, 4; ParJer 7:31); 1º futuro <span class=\"greek\">μνησθήσομαι</span>; 1º aoristo <span class=\"greek\">ἐμνήσθην</span>; perfeito <span class=\"greek\">μέμνημαι</span> (usado como presente [EpArist 168]; cf. B-D-F §341; Rob. 894 f) (reflexivo “fazer-se lembrar, trazer à memória, recordar”, Hom.+).</p><p class=\"entry-text\">① Recuperar informação da memória, lembrar-se, recordar, trazer à lembrança.</p><p class=\"entry-text\">ⓐ Com genitivo da coisa (1 Macc 6:12; TestJob 18:5; ApcMos 23; Just., D. 55, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.75\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:75</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:2</a>; Jd 17; 1 Cl 13:1; 46:7; 50:4; Hv 3, 1, 5.</p><p class=\"entry-text\">ⓑ Com genitivo da pessoa (PBad 48, 17 [126 a.C.] <span class=\"greek\">μνήσθητι</span> <span class=\"greek\">ἡμῶν</span>; ParJer 5:18 <span class=\"greek\">μνησθεὶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰερεμίου</span>; Just., D. 142, 1 <span class=\"greek\">ὡς</span> <span class=\"greek\">φιλῶν</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">μεμνῆσθαι</span>) <span class=\"greek\">πάντα</span> <span class=\"greek\">μου</span> <span class=\"greek\">μέμνησθε</span>, lembrais-vos de mim em todos os aspectos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:2</a> (provavelmente em referência a diversas instruções). Sobre GJs, ver c abaixo.</p><p class=\"entry-text\">ⓒ Seguido de <span class=\"greek\">ὅτι</span> (X., Cyr. 3, 1, 27; Is 12:4; Dt 5:15; Job 7:7; Jos., Vi. 209) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:23</a>; 27:63; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:17</a>, 22; 12:16; GJs 1:3; 10:1, 2 (cada qual com genitivo de pessoa).—Seguido de <span class=\"greek\">ὡς</span> (Ps.-Clem., Hom. 2, 47, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:6</a>. Seguido de genitivo e <span class=\"greek\">ὡς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:16</a>.</p><p class=\"entry-text\">ⓓ Seguido de oração relativa: <span class=\"greek\">μνησθεὶς</span> <span class=\"greek\">ὧς</span> <span class=\"greek\">ἐδίδαξέν</span> <span class=\"greek\">με</span> <span class=\"greek\">μεγαλείων</span>, lembrei-me das grandes coisas que ele me ensinara Hv 4, 1, 8. <span class=\"greek\">μνήσθητι</span>, <span class=\"greek\">ὅσα</span> <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Θεός</span> GJs 9:2.</p><p class=\"entry-text\">② Pensar em algo ou alguém e chamar a atenção para isso, mencionar alguém <span class=\"greek\">τινός</span> (Pardalas Iamb. em Herodes, Cercidas etc., ed. AKnox 1929 p. 276 <span class=\"greek\">μεμνήσομαί</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμῇσι</span> <span class=\"greek\">βύβλοισι</span> = mencionarei a ti em meus livros) EpilMosq 2. De modo semelhante, no passivo: ser mencionado <span class=\"greek\">εἰ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἀβραὰμ</span> <span class=\"greek\">ἐμνήσθη</span> (subentendido <span class=\"greek\">ὁ</span> <span class=\"greek\">λαὸς</span> <span class=\"greek\">οὗτος</span>) 13:7. Aqui também pode pertencer <span class=\"greek\">μνησθῆναι</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, ser mencionado diante de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:19</a>. Mas essas passagens também podem ser compreendidas tendo Deus como sujeito; ver 3 c.</p><p class=\"entry-text\">③ Dedicar cuidadosa consideração a, lembrar, pensar em, cuidar de, preocupar-se com, ter em mente.</p><p class=\"entry-text\">ⓐ Com genitivo (Od. 18, 267 e outros; Arrian, Ind. 41, 5 <span class=\"greek\">δείπνου</span>; Gen 30:22; Jos., Bell. 4, 340; Sib-Or 3, 595) <span class=\"greek\">μνήσθητί</span> <span class=\"greek\">μου</span>, lembra-te de mim <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:42</a> (Epict. 3, 24, 100: ó Deus, <span class=\"greek\">μοῦ</span> <span class=\"greek\">μέμνησο</span>; cf. GDalman, Jesus-Jeshua [tradução PLevertoff] 1929, 197–201; <span class=\"greek\">μοῦ</span> <span class=\"greek\">μέμνησο</span>; TestAbr B 6 p. 110, 11 [Stone p. 68] <span class=\"greek\">ἐμνήσθη</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:6</a> (Ps 8:5); 13:3; D 4:1. <span class=\"greek\">μ</span>. <span class=\"greek\">διαθήκης</span> (cf. <span class=\"greek\">διαθήκη</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.72\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:72</a> (Lev 26:42, 45). <span class=\"greek\">μ</span>. <span class=\"greek\">ἐλέους</span>, versículo 54 (Ps 97:3).—Com genitivo e infinitivo de resultado intencional (B-D-F §391, 4) <span class=\"greek\">μνήσθητι</span>, <span class=\"greek\">κύριε</span>, <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐκκλησίας</span> <span class=\"greek\">σου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ῥύσασθαι</span> <span class=\"greek\">αὐτήν</span>, lembra-te, Senhor, de tua congregação, a fim de salvá-la D 10:5 (GSchmidt, <span class=\"greek\">ΜΝΗΣΘΗΤΙ</span>: Eine liturgiegeschichtliche Skizze, HMeiser Festschr., ’51, 259–64).—<span class=\"greek\">μὴ</span> <span class=\"greek\">μνησθῆναι</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτιῶν</span> <span class=\"greek\">τινος</span>, não recordar os pecados de alguém, deixar sem punição os pecados de alguém (cf. Ps 24:7; 78:8; Sir 23:18; Is 43:25; ApcEsdr 7:11 p. 32, 24 <span class=\"greek\">ἀνομιῶν</span> <span class=\"greek\">ἀρχαίων</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:12</a>; 10:17 (ambos Jer 38:34).</p><p class=\"entry-text\">ⓑ Com acusativo da coisa (Hom.; Hdt. 7, 18; Dt 8:2; Is 63:7.—B-D-F §175; cf. Rob. 482f) <span class=\"greek\">μνησθήσῃ</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">κρίσεως</span>, considerar o dia do juízo 19:10.</p><p class=\"entry-text\">ⓒ Passivo: <span class=\"greek\">αἱ</span> <span class=\"greek\">ἐλεημοσύναι</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἐμνήσθησαν</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, teus atos de caridade foram trazidos à memória por Deus = receberam a atenção de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:31</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:19</a>. <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θ</span>. nessas passagens pode ser entendido como equivalente a <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θ</span>. (<span class=\"greek\">ἐνώπιον</span> 2b; mas ver 2 acima).—CKessler, The Memory Motif in the God-man Relationship of the OT, tese de Northwestern Univ. ’56; B. 1228f. RAC VI 43–54.—LfgrE III 214. Schmidt, Syn. I 310–20. DELG s.v. <span class=\"greek\">μιμνήσκω</span>. M-M. EDNT. TW. Spicq.</p></section></article>"};
